/**
 * @name User input to file operations in pytz
 * @description Check if user-controlled input can reach file open operations in pytz
 * @kind path-problem
 * @problem.severity high
 * @id py/pytz-file-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PytzFileConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for file open operations that we found in the package
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("builtins").getMember(["open", "file"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PytzFileFlow = TaintTracking::Global<PytzFileConfig>;
import PytzFileFlow::PathGraph

from PytzFileFlow::PathNode source, PytzFileFlow::PathNode sink
where PytzFileFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User input reaches file open operation in pytz $@.", source.getNode(), "user input"

/**
 * @name Timezone injection or validation issues
 * @description Check if user-controlled timezone names could cause issues
 * @kind path-problem
 * @problem.severity medium
 * @id py/timezone-injection
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module TimezoneConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for pytz.timezone() calls with user input
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pytz").getMember(["timezone", "zoneinfo"]).getACall() and
      sink = call.getArg(0)
    )
    // Note: Removed datetime tzinfo sink due to parameter index issue
  }
}

module TimezoneFlow = TaintTracking::Global<TimezoneConfig>;
import TimezoneFlow::PathGraph

from TimezoneFlow::PathNode source, TimezoneFlow::PathNode sink
where TimezoneFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled timezone name reaches timezone function $@.", source.getNode(), "user input"
